mapper.select:
select cwe.*, su.student_no as studentNo, su.real_name as studentName from cr_warn_event as cwe left join sys_user as su on cwe.student_id = su.user_id
and su.real_name like concat('%',#{studentName},'%')
and cwe.event_level = #{eventLevel}
and cwe.event_status = #{eventStatus}
and cwe.handler_id = #{handlerId}
order by cwe.create_time desc
